48	const PROCESSING_FEE = 5;
49	const FIRST_INSURANCE_SURCHARGE = 0.1;
50	
51	const BASE_PREMIUMS = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	  moonstone: 25,
58	} as const satisfies Record<string, number>;
59	
60	type InsurableItemType = keyof typeof BASE_PREMIUMS;
61	
62	const basePremiumOf = (item: Item): number =>
63	  BASE_PREMIUMS[item.type as InsurableItemType];
64	
65	/** Premiums are rounded up — in MHPCO's favour. */
66	const roundPremium = (amount: number): number => Math.ceil(amount);
67	
68	const COMPONENT_BLOCK_SIZE = 3;
69	const COMPONENT_BLOCK_PREMIUM = 60;
70	
71	/** Items of a single type, kept together so the block rule can be applied. */
72	type SameTypeGroup = Item[];
73	
74	const groupByType = (items: Item[]): SameTypeGroup[] => {
75	  const groups = new Map<string, SameTypeGroup>();
76	  for (const item of items) {
77	    const group = groups.get(item.type) ?? [];
78	    group.push(item);
79	    groups.set(item.type, group);
80	  }
81	  return [...groups.values()];
82	};
83	
84	const sumBasePremiums = (group: SameTypeGroup): number =>
85	  group.reduce((sum, item) => sum + basePremiumOf(item), 0);
86	
87	/**
88	 * Exactly three alike items form a building block priced at a flat premium;
89	 * any other count is priced per item.
90	 */
91	const blockAwareBasePremium = (group: SameTypeGroup): number =>
92	  group.length === COMPONENT_BLOCK_SIZE
93	    ? COMPONENT_BLOCK_PREMIUM
94	    : sumBasePremiums(group);
95	
96	const policyBasePremiumFor = (items: Item[]): number =>
97	  groupByType(items).reduce(
98	    (sum, group) => sum + blockAwareBasePremium(group),
99	    0,
100	  );
101	
102	const CURSE_SURCHARGE = 0.5;
103	
104	/** A cursed item is surcharged on its own base premium, not the policy's. */
105	const curseSurchargeOn = (item: Item): number =>
106	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE : 0;
107	
108	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
109	const HIGH_ENCHANTMENT_LEVEL = 5;
110	
111	/** Highly enchanted items are surcharged on their own base premium. */
112	const enchantmentSurchargeOn = (item: Item): number =>
113	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
114	    ? basePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE
115	    : 0;
116	
117	/** Item-specific modifiers apply to the base premium of the affected item. */
118	const itemSurcharges = (items: Item[]): number =>
119	  items.reduce(
120	    (sum, item) => sum + curseSurchargeOn(item) + enchantmentSurchargeOn(item),
121	    0,
122	  );
123	
124	const quotePremium = (items: Item[]): number => {
125	  const policyBasePremium = policyBasePremiumFor(items);
126	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE;
127	  return roundPremium(
128	    policyBasePremium +
129	      itemSurcharges(items) +
130	      firstInsuranceSurcharge +
131	      PROCESSING_FEE,
132	  );
133	};
134	
135	const runStep = (step: Step): StepResult => {
136	  if (step.op === "quote") {
137	    return { premium: quotePremium(step.items) };
138	  }
139	  throw new Error(`Unsupported step: ${step.op}`);
140	};
141	
142	export const runScenario = (scenario: Scenario): ScenarioResult => ({
143	  results: scenario.steps.map(runStep),
144	});
